package com.tripnest.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="users") public class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(name="full_name",nullable=false) String fullName; @Column(nullable=false,unique=true) String email; @Column(name="password_hash",nullable=false) String passwordHash; @Enumerated(EnumType.STRING) @Column(nullable=false) Role role=Role.USER; @Column(name="created_at") LocalDateTime createdAt; @Column(name="updated_at") LocalDateTime updatedAt; @PrePersist void create(){createdAt=updatedAt=LocalDateTime.now();} @PreUpdate void update(){updatedAt=LocalDateTime.now();} public Long getId(){return id;} public String getFullName(){return fullName;} public void setFullName(String v){fullName=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPasswordHash(){return passwordHash;} public void setPasswordHash(String v){passwordHash=v;} public Role getRole(){return role;} public void setRole(Role v){role=v;} }
